<?php
require_once __DIR__.'/includes/functions.php'; verify_csrf(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
$name=post_string('name',150);$email=strtolower(post_string('email',150));$phone=post_string('phone',50);$dob=post_string('dob',10);$gender=post_string('gender',10);$password=(string)($_POST['password']??'');
if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$phone||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$dob)||!in_array($gender,['Male','Female','Other'],true)||strlen($password)<8){$error='Please complete all fields correctly. Password must be at least 8 characters.';} else {
try{$db=db();$db->beginTransaction();$s=$db->prepare("INSERT INTO users(role_id,name,email,password_hash,phone,status) VALUES((SELECT id FROM roles WHERE name='patient'),?,?,?,?, 'active')");$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$phone]);$uid=(int)$db->lastInsertId();$num='PAT-'.date('Y').'-'.str_pad((string)$uid,5,'0',STR_PAD_LEFT);$p=$db->prepare('INSERT INTO patients(user_id,patient_number,date_of_birth,gender,full_name,phone) VALUES(?,?,?,?,?,?)');$p->execute([$uid,$num,$dob,$gender,$name,$phone]);$db->commit();flash('success','Account created successfully. You can now sign in.');redirect('login.php');}catch(Throwable $ex){if(db()->inTransaction())db()->rollBack();$error=str_contains(strtolower($ex->getMessage()),'duplicate')?'This email is already registered.':'Registration could not be completed. Please check the database setup.';}}
}
$pageTitle='Patient registration';require __DIR__.'/includes/header.php';?>
<div class="login-wrap"><div class="login-brand"><span class="brand-mark"><i class="bi bi-person-plus-fill"></i></span><h1 class="h3 fw-bold mt-3">Create patient account</h1><p class="text-secondary">Your personal healthcare portal starts here</p></div><div class="card"><div class="card-body p-4 p-md-5"><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post" data-disable-submit><?=csrf_field()?><div class="mb-3"><label class="form-label">Full name</label><input class="form-control" name="name" required maxlength="150" value="<?=e($_POST['name']??'')?>"></div><div class="row"><div class="col-md-7 mb-3"><label class="form-label">Email</label><input class="form-control" type="email" name="email" required value="<?=e($_POST['email']??'')?>"></div><div class="col-md-5 mb-3"><label class="form-label">Phone</label><input class="form-control" name="phone" required value="<?=e($_POST['phone']??'')?>"></div></div><div class="row"><div class="col-md-7 mb-3"><label class="form-label">Date of birth</label><input class="form-control" type="date" name="dob" max="<?=date('Y-m-d')?>" required></div><div class="col-md-5 mb-3"><label class="form-label">Gender</label><select class="form-select" name="gender" required><option value="">Choose…</option><option>Female</option><option>Male</option><option>Other</option></select></div></div><div class="mb-4"><label class="form-label">Password</label><input class="form-control" type="password" name="password" minlength="8" required autocomplete="new-password"><div class="form-text">Use at least 8 characters.</div></div><button class="btn btn-primary w-100 py-2" type="submit">Create account</button></form><p class="text-center small-muted mt-4 mb-0">Already registered? <a href="<?=e(url('login.php'))?>">Sign in</a></p></div></div></div><?php require __DIR__.'/includes/footer.php';?>